import 'dart:async';
import 'dart:js_interop';
import 'dart:js_interop_unsafe';
import 'dart:typed_data';

import 'package:web/web.dart' as web;

import 'device_key.dart';

// Same names as `indexedDbKeyStore` in packages/device-client/src/index.ts.
const String _dbName = 'surau-device';
const String _storeName = 'keys';
const String _recordKey = 'device-key';

/// Device key in the browser: a non-extractable ECDSA P-256 `CryptoKeyPair` generated by
/// WebCrypto and persisted in IndexedDB by structured clone, so the private key bytes are never
/// readable by script. Needs a secure context (HTTPS with the surau root CA trusted, or
/// localhost); without one `crypto.subtle` is missing and every call fails with a BM message.
class WebCryptoDeviceKey implements DeviceKey {
  WebCryptoDeviceKey({String dbName = _dbName}) : _db = dbName;

  final String _db;

  web.SubtleCrypto get _subtle {
    final s = (web.window.crypto as JSObject)['subtle'];
    if (s == null || s.isUndefinedOrNull) {
      throw StateError(
          'Pelayar ini tidak membenarkan kunci peranti. Buka MAXCOM melalui HTTPS');
    }
    return web.window.crypto.subtle;
  }

  Future<web.IDBDatabase> _open() {
    final c = Completer<web.IDBDatabase>();
    final req = web.window.indexedDB.open(_db, 1);
    req.onupgradeneeded = ((web.Event _) {
      (req.result as web.IDBDatabase).createObjectStore(_storeName);
    }).toJS;
    req.onsuccess = ((web.Event _) {
      c.complete(req.result as web.IDBDatabase);
    }).toJS;
    req.onerror = ((web.Event _) {
      c.completeError(StateError('IndexedDB tidak dapat dibuka'));
    }).toJS;
    req.onblocked = ((web.Event _) {
      c.completeError(StateError('IndexedDB tidak dapat dibuka'));
    }).toJS;
    return c.future;
  }

  Future<JSAny?> _run(
    String mode,
    web.IDBRequest Function(web.IDBObjectStore s) make,
  ) async {
    final db = await _open();
    try {
      final c = Completer<JSAny?>();
      final tx = db.transaction(_storeName.toJS, mode);
      final req = make(tx.objectStore(_storeName));
      tx.oncomplete = ((web.Event _) => c.complete(req.result)).toJS;
      tx.onerror = ((web.Event _) =>
          c.completeError(StateError('IndexedDB gagal'))).toJS;
      tx.onabort = ((web.Event _) =>
          c.completeError(StateError('IndexedDB gagal'))).toJS;
      return await c.future;
    } finally {
      db.close();
    }
  }

  Future<JSObject?> _pair() async {
    final v = await _run('readonly', (s) => s.get(_recordKey.toJS));
    if (v == null || v.isUndefinedOrNull) return null;
    final o = v as JSObject;
    final priv = o['privateKey'];
    final pub = o['publicKey'];
    if (priv == null || pub == null || priv.isUndefinedOrNull) return null;
    // Refuse a record whose private key is exportable: it was not made by this code.
    if ((priv as web.CryptoKey).extractable) return null;
    return o;
  }

  @override
  Future<bool> exists() async {
    try {
      return await _pair() != null;
    } catch (_) {
      return false;
    }
  }

  @override
  Future<Map<String, String>> generate() async {
    final subtle = _subtle;
    final algo = {'name': 'ECDSA', 'namedCurve': 'P-256'}.jsify()!;
    final usages = <JSString>['sign'.toJS, 'verify'.toJS].toJS;
    final pair =
        (await subtle.generateKey(algo, false, usages).toDart) as JSObject;
    final jwk = await _exportPublic(pair['publicKey']! as web.CryptoKey);
    await _run('readwrite', (s) => s.put(pair, _recordKey.toJS));
    await deviceKeySelfCheck(this, jwk);
    return jwk;
  }

  Future<Map<String, String>> _exportPublic(web.CryptoKey pub) async {
    final raw =
        (await _subtle.exportKey('jwk', pub).toDart) as JSObject;
    String field(String k) {
      final v = raw[k];
      if (v == null || !v.isA<JSString>()) {
        throw StateError('Kunci awam tidak sah');
      }
      return (v as JSString).toDart;
    }

    // Exactly {kty, crv, x, y}: drop ext, key_ops and anything else the browser adds.
    final jwk = {
      'kty': field('kty'),
      'crv': field('crv'),
      'x': field('x'),
      'y': field('y'),
    };
    if (jwk['kty'] != 'EC' || jwk['crv'] != 'P-256') {
      throw StateError('Kunci awam tidak sah');
    }
    return jwk;
  }

  @override
  Future<Map<String, String>> publicJwk() async {
    final p = await _pair();
    if (p == null) throw StateError('Kunci peranti tiada. Daftar semula peranti ini');
    return _exportPublic(p['publicKey']! as web.CryptoKey);
  }

  @override
  Future<Uint8List> sign(Uint8List message) async {
    final p = await _pair();
    if (p == null) throw StateError('Kunci peranti tiada. Daftar semula peranti ini');
    final algo = {'name': 'ECDSA', 'hash': 'SHA-256'}.jsify()!;
    final out = await _subtle
        .sign(algo, p['privateKey']! as web.CryptoKey, message.toJS)
        .toDart;
    // WebCrypto already returns IEEE P1363 (r||s), 64 bytes for P-256.
    final bytes = Uint8List.fromList((out as JSArrayBuffer).toDart.asUint8List());
    if (bytes.length != 64) throw StateError('Tandatangan tidak sah');
    return bytes;
  }

  @override
  Future<void> clear() async {
    try {
      await _run('readwrite', (s) => s.delete(_recordKey.toJS));
    } catch (_) {
      // No store or no key: nothing usable remains either way.
    }
  }
}

DeviceKey createPlatformDeviceKey() => WebCryptoDeviceKey();
